2a77;z-index:50;display:none}.scrim.open{display:block}.drawer header{position:static;border:0;display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.cart-line{padding:10px 0;border-bottom:1px solid var(--line);display:grid;grid-template-columns:1fr 80px 35px;gap:8px;align-items:center}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.form-grid>*{min-width:0}.totals{font-size:16px;display:flex;justify-content:space-between;margin:12px 0}.success{background:#e9f9ee;color:#156a42;padding:12px;border-radius:10px;margin:10px 0}.error{background:#fff0f0;color:#942c3e;padding:12px;border-radius:10px}.pages{padding:20px 0 60px}footer{padding:30px 0;border-top:1px solid var(--line);color:var(--text)}
@media(max-width:1080px){.catalog{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:780px){.catalog{grid-template-columns:repeat(2,minmax(0,1fr))}.hero{display:block}.search{max-width:450px}}@media(max-width:460px){.catalog{gap:10px}.item-art{height:120px}.item-body{padding:11px}.nav{padding:10px 0}.item .price{font-size:17px}.form-grid{grid-template-columns:1fr}}
</style></head>
