<div class="catalog">
<?php $__empty_1 = true; $__currentLoopData = $products; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $product): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?>
<article class="item"><div class="item-art"><?php if($product->image_url): ?><img loading="lazy" src="<?php echo e($product->image_url); ?>" alt="<?php echo e($product->name); ?>"><?php else: ?><span>◈</span><?php endif; ?></div><div class="item-body"><h3><?php echo e($product->name); ?></h3><div class="hint"><?php echo e($product->sku); ?></div><div class="price">৳<?php echo e(number_format($product->variants->min('price')??$product->price,2)); ?></div>
<select class="field" id="variant-<?php echo e($product->id); ?>" aria-label="<?php echo e(t('Choose variant','ভ্যারিয়েন্ট বাছুন')); ?>">
<?php $__currentLoopData = $product->variants; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $variant): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?>
<option value="<?php echo e($variant->id); ?>" data-name="<?php echo e($product->name); ?> / <?php echo e($variant->sku); ?>" data-price="<?php echo e($variant->price); ?>" data-stock="<?php echo e($product->track_stock ? $variant->stock : 999); ?>" <?php if($product->track_stock && $variant->stock<=0): echo 'disabled'; endif; ?>><?php echo e($variant->size?->name); ?> <?php echo e($variant->color?->name); ?> <?php echo e($variant->sku); ?> · ৳<?php echo e(number_format($variant->price,2)); ?> <?php echo e($product->track_stock?'('.$variant->stock.' left)':''); ?></option>
<?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button class="btn add-to-cart" type="button" data-product="<?php echo e($product->id); ?>">+ <?php echo e(t('Add to Cart','কার্টে যোগ করুন')); ?></button></div></article>
<?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="empty"><?php echo e(t('No products yet.','এখনও কোনো পণ্য নেই।')); ?></div><?php endif; ?>
</div><div class="pages"><?php echo e($products->links()); ?></div></main>
<div class="scrim" id="scrim"></div><aside class="drawer" id="drawer" role="dialog" aria-modal="true" aria-label="Shopping cart"><header><h2><?php echo e(t('Your Cart','আপনার কার্ট')); ?></h2><button class="btn outline" type="button" id="close-cart">×</button></header>
<div id="cart-rows"></div><div class="totals"><b><?php echo e(t('Items Subtotal','পণ্যের মূল্য')); ?></b><b id="subtotal">৳0.00</b></div>
<form id="checkout-form" method="POST" action="<?php echo e(route('store.customer.shop.checkout')); ?>"><?php echo csrf_field(); ?><input type="hidden" name="request_key" value="<?php echo e((string) \Illuminate\Support\Str::uuid()); ?>"><div id="checkout-items"></div>
<h3><?php echo e(t('Delivery Information','ডেলিভারি তথ্য')); ?></h3><div class="form-grid"><div><label class="hint"><?php echo e(t('Name','নাম')); ?></label><input name="customer_name" class="field" required maxlength="255"></div><div><label class="hint"><?php echo e(t('Phone','ফোন')); ?></label><input name="customer_phone" class="field" required maxlength="40"></div></div><div style="margin-top:9px"><label class="hint"><?php echo e(t('Full Address','সম্পূর্ণ ঠিকানা')); ?></label><textarea class="field" name="customer_address" required rows="3"></textarea></div>
<div style="margin-top:9px"><label class="hint"><?php echo e(t('Email (required for online payment)','ইমেইল (অনলাইন পেমেন্টে আবশ্যক)')); ?></label><input class="field" type="email" name="customer_email" maxlength="255"></div>
<div style="margin-top:9px"><label class="hint"><?php echo e(t('Payment','পেমেন্ট')); ?></label><select class="field" name="payment_choice" id="payment-choice"><option value="cod"><?php echo e(t('Cash on Delivery','ক্যাশ অন ডেলিভারি')); ?></option><?php if($onlinePaymentEnabled): ?><option value="sslcommerz"><?php echo e(t('Secure Online Payment','নিরাপদ অনলাইন পেমেন্ট')); ?></option><?php endif; ?></select></div>
<div style="margin-top:9px"><label class="hint"><input type="checkbox" name="marketing_opt_in" value="1" id="marketing-opt-in"> <?php echo e(t('I agree to save my cart and be contacted about offers.','অফার সম্পর্কে যোগাযোগ ও কার্ট সংরক্ষণে সম্মতি দিচ্ছি।')); ?></label></div>
<div style="margin-top:9px"><label class="hint"><?php echo e(t('Delivery Method','ডেলিভারি পদ্ধতি')); ?></label><select class="field" name="shipping_method_id" id="shipping-method"><option value="" data-charge="0"><?php echo e(t('Arrange delivery later','পরে ডেলিভারি ঠিক করুন')); ?></option><?php $__currentLoopData = $shippings; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $shipping): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($shipping->id); ?>" data-charge="<?php echo e($shipping->charge); ?>"><?php echo e($shipping->name); ?> (৳<?php echo e(number_format($shipping->charge,2)); ?>)</option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div>
<div style="margin-top:9px"><label class="hint"><?php echo e(t('Coupon Code','কুপন কোড')); ?></label><input class="field" name="coupon_code"></div><div class="totals"><b><?php echo e(t('Before discount / delivery','ছাড় ও ডেলিভারি চার্জের আগে')); ?></b><b id="checkout-total">৳0.00</b></div>
<p class="hint"><?php echo e(t('For online payment, the gateway verifies the amount before we record a payment. Discounts are verified on the server.','অনলাইন পেমেন্ট যাচাই হওয়ার পর হিসাব পোস্ট হবে। ছাড় সার্ভারে যাচাই হবে।')); ?></p>
<button class="btn" style="width:100%" type="submit"><?php echo e(t('Place Order','অর্ডার করুন')); ?></button></form></aside>
<footer><div class="shell">© <?php echo e(date('Y')); ?> <?php echo e($b->name); ?> · <?php echo e(t('Shop securely','নিরাপদে কেনাকাটা করুন')); ?></div></footer>
<script>
(()=>{const key='retail-cart:<?php echo e($b->id); ?>',cart=new Map();try{for(const r of JSON.parse(localStorage.getItem(key)||'[]'))cart.set(String(r.id),r)}catch(e){}const $=id=>document.getElementById(id),money=x=>'৳'+Number(x).toFixed(2);const buttons=[...document.querySelectorAll('.add-to-cart')];
function safe(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;')}
function save(){localStorage.setItem(key,JSON.stringify([...cart.values()]));render()}
function render(){const holder=$('cart-rows'),hidden=$('checkout-items');holder.replaceChildren();hidden.replaceChildren();let subtotal=0,count=0,i=0;for(const [id,row] of cart){subtotal+=row.price*row.qty;count+=row.qty;const div=document.createElement('div');div.className='cart-line';div.innerHTML=`<div><strong>${safe(row.name)}</strong><div class="hint">${money(row.price)}</div></div><input class="field" type="number" min="1" step="1" max="${Math.max(1,Number(row.stock))}" value="${row.qty}"><button type="button" class="btn outline">×</button>`;div.querySelector('input').onchange=e=>{row.qty=Math.max(1,Math.min(row.stock,Math.floor(Number(e.target.value)||1)));save()};div.querySelector('button').onclick=()=>{cart.delete(id);save()};holder.append(div);for(const [name,value] of Object.entries({variant_id:id,quantity:row.qty})){let input=document.createElement('input');input.type='hidden';input.name=`items[${i}][${name}]`;input.value=value;hidden.append(input)}i++}
$('cart-count').textContent=count;$('subtotal').textContent=money(subtotal);const opt=$('shipping-method').selectedOptions[0];$('checkout-total').textContent=money(subtotal+Number(opt?.dataset.charge||0));}
buttons.forEach(btn=>btn.addEventListener('click',()=>{const select=$('variant-'+btn.dataset.product),v=select.selectedOptions[0];if(!v||!v.value||v.disabled)return;let id=v.value,stock=Math.floor(Number(v.dataset.stock));if(stock<1)return;let row=cart.get(id);if(row){if(row.qty<stock)row.qty++;}else cart.set(id,{id,stock,qty:1,name:v.dataset.name,price:Number(v.dataset.price)});save();$('drawer').classList.add('open');$('scrim').classList.add('open')}));
$('open-cart').onclick=()=>{$('drawer').classList.add('open');$('scrim').classList.add('open')};$('close-cart').onclick=$('scrim').onclick=()=>{$('drawer').classList.remove('open');$('scrim').classList.remove('open')};$('shipping-method').onchange=render;$('checkout-form').onsubmit=e=>{if(cart.size===0){e.preventDefault();alert('Select products first');return}e.target.querySelector('button[type=submit]').disabled=true;};
let cartTimer;function marketingSave(){if(!$('marketing-opt-in').checked)return;const form=$('checkout-form');if(!form.querySelector('[name=customer_phone]')?.value?.trim())return;const fd=new FormData(form);fd.set('marketing_opt_in','1');fetch(<?php echo json_encode(route('store.customer.shop.abandoned'), 15, 512) ?>,{method:'POST',body:fd,credentials:'same-origin',headers:{'Accept':'application/json'}}).catch(()=>{});}['input','change'].forEach(evt=>$('checkout-form').addEventListener(evt,()=>{clearTimeout(cartTimer);cartTimer=setTimeout(marketingSave,1500)}));
$('payment-choice').onchange=()=>{const email=$('checkout-form').querySelector('[name=customer_email]');email.required=$('payment-choice').value==='sslcommerz';};
$('theme-button').onclick=()=>{let t=document.documentElement.getAttribute('data-theme')==='dark'?'light':'dark';document.documentElement.setAttribute('data-theme',t);try{localStorage.setItem('saas-ui-theme',t)}catch(e){}};render();})();
</script>
